cat >> hbexpense/util/text.py <<'EOF'


def clip_bytes(text, limit):
    """Cut text to at most `limit` UTF-8 bytes, on a character boundary."""
    if limit <= 0:
        return ""
    data = text.encode("utf-8")
    if len(data) <= limit:
        return text
    return data[:limit].decode("utf-8", errors="ignore").rstrip()
EOF
